  const binaries = $input.first().binary || {};
  const bin = binaries.data || binaries.file || binaries[Object.keys(binaries)[0]];
  if (!bin) throw new Error('Sin archivo adjunto.');
  const mime = (bin.mimeType || 'application/pdf').split(';')[0].trim();
  const allowed = ['application/pdf','image/jpeg','image/png','image/webp'];
  if (!allowed.includes(mime)) throw new Error('Tipo no soportado: ' + mime);

  let apiKey = 'AIzaSyAZIGKq7uaoRMS9-GYiTf_ul81pkCwoJew';
  const bodyParams = $input.first().json.body;
  if (bodyParams && bodyParams.apiKey && bodyParams.apiKey.trim() !== '') {
    apiKey = bodyParams.apiKey.trim();
  }

  return [{ json: { fileName: bin.fileName||'doc.pdf', mimeType: mime, apiKey: apiKey }, binary: { data: bin } }];
} catch(e) { throw new Error('❌ Normalizar: ' + e.message); }

const r = $input.first().json;
const uri = (r.file && r.file.uri) ? r.file.uri : r.uri;
if (!uri) throw new Error('No se obtuvo URI de Gemini.');
const mime = $('Normalizar').first().json.mimeType;
const apiKey = $('Normalizar').first().json.apiKey;

const body = {
  system_instruction: { parts: [{ text: 'Mapeador de exámenes. Responde SOLO JSON válido.' }] },
  contents: [{ parts: [
    { file_data: { mime_type: mime, file_uri: uri } },
    { text: 'Identifica cuántas preguntas hay en total y a qué curso pertenece cada una.\nNO extraigas el texto de las preguntas ahora.\n\nResponde SOLO este JSON:\n{\n "total": 20,\n "lista": [ { "id": 1, "curso": "Nombre" }, ... ]\n}' }
  ]}],
  generationConfig: {
    temperature: 0.1,
    maxOutputTokens: 2000,
    responseMimeType: 'application/json'
  }
};

return [{ json: { requestBody: JSON.stringify(body), fileUri: uri, mimeType: mime, apiKey: apiKey } }];

const resp = $input.first().json;
const raw = resp.candidates?.[0]?.content?.parts?.[0]?.text;
if (!raw) throw new Error('Respuesta vacía de Gemini Mapeo');

const mapData = JSON.parse(raw.replace(/```json\s*/gi,'').replace(/```\s*/gi,'').trim());
const lista = mapData.lista || [];
if (!lista.length) throw new Error('No se encontraron preguntas en el mapeo.');

const fileUri = $('Prompt Mapeo').first().json.fileUri;
const mimeType = $('Prompt Mapeo').first().json.mimeType;
const apiKey = $('Prompt Mapeo').first().json.apiKey;

// Dividir en bloques de 8 preguntas (seguro para 2.5-flash con thinking)
const size = 8;
const lotes = [];
for (let i = 0; i < lista.length; i += size) {
  const slice = lista.slice(i, i + size);
  lotes.push({ json: { 
    bloque_num: Math.floor(i/size)+1, 
    ids: slice.map(x => x.id), 
    cursos: slice.map(x => x.curso), 
    fileUri, mimeType, apiKey 
  } });
}

return lotes;

const { ids, cursos, fileUri, mimeType, apiKey } = $input.item.json;

const rando = ids.join(', ');

const body = {
  system_instruction: { parts: [{ text: `Profesor experto. Responde SOLO JSON válido.` }] },
  contents: [{ parts: [
    { file_data: { mime_type: mimeType, file_uri: fileUri } },
    { text: `Localiza en el documento las preguntas con estos IDs: ${rando}.\nExtráelas y resuélvelas.\n\nREGLAS:\n- Ciencias: LaTeX inline $formula$, máx 3 pasos.\n- Letras: Justificación 1 línea.\n- Incluye el texto original de la pregunta.\n\nJSON (soluciones:[]):` }
  ]}],
  generationConfig: {
    temperature: 0.1,
    maxOutputTokens: 8192,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        soluciones: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              ID_Secuencial: { type: 'INTEGER' },
              Curso: { type: 'STRING' },
              Pregunta_Texto: { type: 'STRING' },
              Desarrollo: { type: 'STRING' },
              Respuesta_Final: { type: 'STRING' }
            },
            required: ['ID_Secuencial','Curso','Pregunta_Texto','Desarrollo','Respuesta_Final']
          }
        }
      },
      required: ['soluciones']
    }
  }
};

return [{ json: { requestBody: JSON.stringify(body), apiKey } }];

const resp = $input.item.json;
try {
  const raw = resp.candidates?.[0]?.content?.parts?.[0]?.text;
  const solData = JSON.parse(raw.replace(/```json\s*/gi,'').replace(/```\s*/gi,'').trim());
  return [{ json: { soluciones: solData.soluciones || [] } }];
} catch(e) {
  return [{ json: { soluciones: [], error: e.message } }];
}

const todos = $input.all().map(i => i.json);
const sols = todos.flatMap(t => t.soluciones);

const cursosMap = {};
sols.forEach(s => {
  const c = s.Curso || 'General';
  if (!cursosMap[c]) cursosMap[c] = [];
  cursosMap[c].push(s);
});

const COLORES = ['#4f46e5', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];
const cursosHtml = Object.entries(cursosMap).map(([curso, items], idx) => {
  const color = COLORES[idx % COLORES.length];
  const divs = items.map(s => `
    <div class="si">
      <div class="sn">#${s.ID_Secuencial}</div>
      <div class="sq">${String(s.Pregunta_Texto).replace(/</g,'&lt;').replace(/>/g,'&gt;')}</div>
      <div class="sd">${String(s.Desarrollo).replace(/</g,'&lt;').replace(/>/g,'&gt;')}</div>
      <div class="sa">✅ <strong>${String(s.Respuesta_Final).replace(/</g,'&lt;').replace(/>/g,'&gt;')}</strong></div>
    </div>`).join('');
  return `<div class="cb" style="border-top:4px solid ${color}">
    <div class="ct" style="background:${color}">${curso} <span class="badge">${items.length}</span></div>
    <div class="sl">${divs}</div>
  </div>`;
}).join('');

const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
<script>window.MathJax={tex:{inlineMath:[['$','$']]}};<\/script>
<script async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"><\/script>
<style>
body{font-family:Arial,sans-serif;max-width:960px;margin:30px auto;padding:20px;background:#f1f5f9;color:#1e293b}
h1{text-align:center;font-size:1.6rem}
.cb{background:#fff;border-radius:10px;margin-bottom:18px;overflow:hidden;box-shadow:0 2px 10px rgba(0,0,0,.07)}
.ct{color:#fff;padding:11px 18px;font-weight:700;display:flex;justify-content:space-between}
.badge{background:rgba(255,255,255,.25);padding:1px 10px;border-radius:99px}
.sl{padding:18px}
.si{margin-bottom:20px;padding-bottom:20px;border-bottom:1px solid #f1f5f9}
.sn{font-size:.7rem;color:#94a3b8;margin-bottom:6px}
.sq{font-size:.8rem;color:#64748b;margin-bottom:6px;font-style:italic}
.sd{font-size:.9rem;line-height:1.7;white-space:pre-wrap}
.sa{margin-top:10px;padding:9px 14px;background:#dcfce7;border-left:4px solid #22c55e;border-radius:0 7px 7px 0}
</style></head><body><h1>🎓 Solucionario IA v11</h1>${cursosHtml}</body></html>`;

return [{ json: { html_content: html, total: sols.length } }];
